{
    server_t *server = get_server();

    for (int i = 0; server->arg.teams[i]; i++) {
        server->arg.teams[i]->nbr_current = nbr_max;
        server->arg.teams[i]->nbr_max = MAX_PLAYER_SAME_POSITION * 10;
    }
}

int check_param_width_and_height(server_t *server)
