bool is_death(client_t *client)
{
    server_t *server = get_server();

    client->tick_food = 0;
    if (client->food >= 1)
        return (false);
    remove_player_to_cell(client->x, client->y, client);
    for (int i = 0; server->arg.teams[i]; i++)
        if (strcmp(server->arg.teams[i]->name, client->name) == 0) {
